INSERT INTO comments (page, parent_id, name, ort, body, created_at, date_precision, status, is_team, source) VALUES ('gaestebuch', NULL, 'pommes', NULL, 'Ich erinnere mich an ein total geiles Konzert zusammen mit „Gypsy Child" in der Halle in Sulzgrün – war einfach nur eine mega tolle Zeit!!! Viel Erfolg, ich freu mich jetzt schon auf den Film.', '2018-07-24', 'year', 'approved', 0, 'wix');
