INSERT INTO comments (page, parent_id, name, ort, body, created_at, date_precision, status, is_team, source) VALUES ('gaestebuch', NULL, 'Lukas', NULL, 'Wow, ich hab Scaramouche zwar nie live erlebt, bin wohl noch zu jung. Aber ich werd''s mir trotzdem angucken. Eine Kinodoku aus Lahr. Geil...', '2019-07-24', 'year', 'approved', 0, 'wix');
INSERT INTO comments (page, parent_id, name, ort, body, created_at, date_precision, status, is_team, source) VALUES ('gaestebuch', NULL, 'Elke S.', NULL, 'Wow, was für ein tolles Video ihr da zum Crowdfunding gedreht habt. Das macht Lust auf den Film. Und da ich den Film unbedingt möchte, habe ich mich natürlich schon beteiligt. Ich freu mich soooo!', '2019-07-24', 'year', 'approved', 0, 'wix');
INSERT INTO comments (page, parent_id, name, ort, body, created_at, date_precision, status, is_team, source) VALUES ('gaestebuch', NULL, 'claus-Dieter ruf (Doctor)', NULL, 'Vorschlag von mir: Macht doch ein Reunion-Konzert von Scaramouche im Schlachthof, und den Eintritt nehmt ihr zur Finanzierung. Der Laden wird mit Sicherheit voll. Habe früher alle Konzerte mitgenommen. Kenne Marc und Gert schon lange, bin selber Musiker.', '2019-07-24', 'year', 'approved', 0, 'wix');
INSERT INTO comments (page, parent_id, name, ort, body, created_at, date_precision, status, is_team, source) VALUES ('gaestebuch', NULL, 'Niclas Haas', NULL, 'Ich kenn die Band leider nicht so gut aber die Musik ist echt nice und Herr Vetter ist mein Lehrer und ich feier seine Musik voll und freu mich auch über den Film.', '2019-07-24', 'year', 'approved', 0, 'wix');
