INSERT INTO comments (page, parent_id, name, ort, body, created_at, date_precision, status, is_team, source) VALUES ('gaestebuch', NULL, 'Sven', NULL, 'Hallo, ich hoffe euch geht''s allen gut. Wollte mal nachfragen ob es schon eine weitere Planung für das Projekt gibt. Wir freuen uns.', '2021-07-24', 'year', 'approved', 0, 'wix');
