INSERT INTO comments (page, parent_id, name, ort, body, created_at, date_precision, status, is_team, source) VALUES ('gaestebuch', (SELECT MAX(id) FROM comments), 'Pirmin', NULL, 'Es geht definitiv weiter. Wir mussten wegen Corona leider eine ungeplante und sehr deprimierende Auszeit nehmen. Aber seit März laufen die Kameras wieder.', '2023-07-24', 'year', 'approved', 1, 'wix');
INSERT INTO comments (page, parent_id, name, ort, body, created_at, date_precision, status, is_team, source) VALUES ('gaestebuch', NULL, 'Der_Ex-Lohrer', NULL, 'Schwingt die Hufe! Wir wollen endlich was über SCARAMOUCHE sehen. Bald 25 Jahre her, dass wir vor der Bühne im Stadtpark abgefeiert haben. Grüße gehen raus an alle Lohrer. „I believe in the Queen of England"!!!', '2023-07-24', 'year', 'approved', 0, 'wix');
