INSERT INTO comments (page, parent_id, name, ort, body, created_at, date_precision, status, is_team, source) VALUES ('gaestebuch', (SELECT MAX(id) FROM comments), 'Pirmin', NULL, 'Hi Liane, danke für deine Frage! Wir drehen schon seit einer ganzen Weile wieder, aber dein Eintrag hier hat mich inspiriert endlich wieder einen Eintrag in den Blog zu machen. Ja, es geht weiter. Und wir freuen uns sehr darüber!', '2023-07-24', 'year', 'approved', 1, 'wix');
