INSERT INTO comments (page, parent_id, name, ort, body, created_at, date_precision, status, is_team, source) VALUES ('gaestebuch', NULL, 'Sven', NULL, 'Hallo zusammen, wollte mal nach einem Update fragen. Wie sieht es denn aus – gibt es irgendwann einen Film oder ist das Projekt beendet? Wäre schön mal wieder was zu hören, am besten mit einem ungefähren Zeitplan.', '2025-07-24', 'year', 'approved', 0, 'wix');
