INSERT INTO comments (page, parent_id, name, ort, body, created_at, date_precision, status, is_team, source) VALUES ('gaestebuch', NULL, 'Entsetzt!', 'Lahr', 'Werden nun auch noch Kommentare gelöscht?! Also jetzt fängt die Sache an zu stinken.', '2026-09-29', 'exact', 'approved', 0, 'manual');
INSERT INTO comments (page, parent_id, name, ort, body, created_at, date_precision, status, is_team, source) VALUES ('gaestebuch', (SELECT MAX(id) FROM comments), 'Maik', NULL, 'Hallo, das tut uns leid – und die Frage ist berechtigt, wenn plötzlich etwas fehlt. Absichtlich gelöscht haben wir nichts. Die Seite ist gerade frisch umgezogen, weg vom alten Anbieter, wenn dabei Beiträge auf der Strecke geblieben sind, wäre das natürlich schlecht. Wenn du weißt, welcher Beitrag fehlt, schreib es uns kurz – dann suchen wir gezielt danach. Danke, dass du nachgefragt hast.', '2026-09-29', 'exact', 'approved', 1, 'manual');
INSERT INTO comments (page, name, body, created_at, date_precision, status, source, flag_reason) VALUES ('blog/ein-drehtag-in-der-rockfabrik-heart-and-soul-im-rocker-paradies', 'lecteurolwrglkjogzov', 'To był niesamowity dzień w Rockfabrik. Materiał Heart and Soul wyszedł fantastycznie i idealnie oddaje klimat tego rockowego raju.', '2026-09-10', 'exact', 'approved', 'wix', NULL);
INSERT INTO comments (page, name, body, created_at, date_precision, status, source, flag_reason) VALUES ('blog/badischer-underground-bon-jovi-und-andere-proberaumgeschichten', 'Scott S. Walker', 'Der Artikel zeigt auf unterhaltsame Weise, wie wichtig die professionelle Restaurierung und Digitalisierung alter Tonbänder sein kann. Besonders spannend finde ich, dass die scheinbar ungewöhnliche Methode des vorsichtigen Erwärmens tatsächlich Teil eines professionellen Rettungsprozesses für beschädigte Bänder sein kann. Im beschriebenen Fall konnten dadurch alte Studioaufnahmen gerettet und für eine Musikdokumentation digitalisiert werden. Solche Geschichten machen deutlich, wie wertvoll historische Tonaufnahmen sind und wie viel Fachwissen nötig ist, um sie langfristig zu erhalten.', '2026-08-27', 'exact', 'approved', 'wix', NULL);
INSERT INTO comments (page, name, body, created_at, date_precision, status, source, flag_reason) VALUES ('blog/scaramouche-unplugged-bei-swr1', 'Shakib Hasan', 'What a fascinating behind-the-scenes story! I love how it shows that genuine musical chemistry can survive even after many years apart. The idea of rehearsing during a car ride adds a fun and authentic touch, making the reunion feel even more special. Thanks for sharing this memorable moment and the passion behind it—I’m looking forward to reading more stories that capture the people and emotions behind the music.', '2026-07-27', 'exact', 'approved', 'wix', NULL);
INSERT INTO comments (page, name, body, created_at, date_precision, status, source, flag_reason) VALUES ('blog/badischer-underground-bon-jovi-und-andere-proberaumgeschichten', 'Kendell Ruffin', 'Solche Proberaumgeschichten wecken sofort Erinnerungen an eigene musikalische Erlebnisse. Gerade die Mischung aus lokalen Bands, spontanen Ideen und kleinen Pannen macht vieles authentisch. Beim Lesen musste ich an frühere Begegnungen denken, die oft unerwartete Wendungen nahmen. Auch ein Branchenbuch kann manchmal dabei helfen, interessante Kontakte aus der Musikszene zu entdecken. Die beschriebenen Momente wirken glaubwürdig und vermitteln eine besondere Atmosphäre. Vielen Dank für diese Einblicke, über ähnliche Erfahrungen liest man immer wieder gerne.', '2026-06-11', 'exact', 'approved', 'wix', NULL);
INSERT INTO comments (page, name, body, created_at, date_precision, status, source, flag_reason) VALUES ('blog/ein-drehtag-in-der-rockfabrik-heart-and-soul-im-rocker-paradies', 'Oleg Garmash', 'Часом знаходжу ці джерела випадково, іноді хтось скине в чат, іноді сам зберігаю "на потім". Частину переглядаю рідко, частину — коли шукаю щось локальне чи нестандартне. Вони різні: новини, огляди, думки, регіональні стрічки. Я не беру все за правду — скоріше, для порівняння та пошуку контрасту між подачею. Можливо, хтось іще знайде серед них щось цікаве або принаймні нове. Головне — мати з чого обирати.', '2026-01-12', 'exact', 'pending', 'wix', 'Linkfarm: bestand fast nur aus Spam-Links');
INSERT INTO comments (page, name, body, created_at, date_precision, status, source, flag_reason) VALUES ('blog/ein-drehtag-in-der-rockfabrik-heart-and-soul-im-rocker-paradies', 'Oleg Garmash', 'Часом знаходжу ці джерела випадково, іноді хтось скине в чат, іноді сам зберігаю "на потім". Частину переглядаю рідко, частину — коли шукаю щось локальне чи нестандартне. Вони різні: новини, огляди, думки, регіональні стрічки. Я не беру все за правду — скоріше, для порівняння та пошуку контрасту між подачею. Можливо, хтось іще знайде серед них щось цікаве або принаймні нове. Головне — мати з чого обирати.', '2026-01-12', 'exact', 'pending', 'wix', 'Linkfarm: bestand fast nur aus Spam-Links');
INSERT INTO comments (page, name, body, created_at, date_precision, status, source, flag_reason) VALUES ('blog/scaramouche-unplugged-bei-swr1', 'rehr grge', 'Es ist faszinierend, wie viele Informationen in digitalen Bildern verborgen sind, oft ohne dass wir uns dessen bewusst sind, wenn wir sie teilen oder archivieren. Das reicht von Kameramodellen bis hin zu genauen Aufnahmeorten. Gerade wenn es um den Schutz der Privatsphäre oder die detaillierte Analyse von Fotos geht, ist es entscheidend, diese Metadaten lesen und verstehen zu können. Dafür gibt es nützliche Ressourcen, um die EXIF-Daten aus Bildern auszulesen und so volle Kontrolle über die eigenen Bildinformationen zu behalten.', '2025-09-23', 'exact', 'approved', 'wix', NULL);
INSERT INTO comments (page, name, body, created_at, date_precision, status, source, flag_reason) VALUES ('blog/knapp-30-000-menschen-bei-einem-festival-in-lahr-das-ist-doch-toll', 'kianfinnegan691', 'Good reaading', '2021-10-17', 'exact', 'approved', 'wix', NULL);
INSERT INTO comments (page, name, body, created_at, date_precision, status, source, flag_reason) VALUES ('blog/scaramouche-unplugged-bei-swr1', 'photo lab', 'sehr interessanter Blog. Vielen Dank für den Austausch nützlicher Informationen. es hat mir sehr gefallen. Viel Glück! Wenn Sie Freizeit haben, empfehle ich Ihnen, sich mit den Informationen vertraut zu machen, die Ihnen in Zukunft helfen werden, die Konzertfotografie effizienter zu gestalten. ich denke du wirst es mögen', '2020-10-08', 'exact', 'approved', 'wix', NULL);
INSERT INTO comments (page, name, body, created_at, date_precision, status, source) VALUES ('gaestebuch', 'Ein verärgerter Spender!!!', 'Also irgendwie erweckt sich hier der Verdacht, dass das gesammlte Geld anders verwendet wurde. Keinerlei Bewegung mehr in diesem Projekt. Kein Statement, einfach nichts! Hier wäre es wünschenswert wenn man dazu endlich mal ein Feedback bekommen könnte. Ansonsten allen Spendern das Geld wieder zurückzahlen, da es kein Resultat bzw. Endergebnis gibt. Dafür sind solche Sammelaktionen nämlich nicht gedacht.', '2026-09-17', 'exact', 'approved', 'wix');
INSERT INTO comments (page, parent_id, name, body, created_at, date_precision, status, is_team, source) VALUES ('gaestebuch', (SELECT MAX(id) FROM comments), 'Filmteam', 'Hallo, wir stimmen dir zu – es war viel zu lange still hier, und dafür entschuldigen wir uns. Das Projekt liegt nicht auf Eis: Nach einigen Rückschlägen geht es weiter, allerdings deutlich langsamer als ursprünglich geplant. In Kürze melden wir uns mit einem ausführlichen Update im Blog, in dem wir offen erzählen, was passiert ist, wo wir stehen und wie es weitergeht. Danke fürs Nachhaken.', '2026-09-29', 'exact', 'approved', 1, 'manual');
